const itoLogo = (t) => `<g transform="${t}"><path d="${LEAF}" fill="#fff" stroke="#fff" stroke-width="1.1" stroke-linejoin="round"/><path d="${LEAF}" fill="#169c46"/><path d="${ITOEN}" fill="#065a2b" fill-rule="evenodd" stroke="#065a2b" stroke-width=".22"/></g>`;

// Molded ribs of the lower bottle section (same 500 mL bottle family, measured on both packshots).
const ribs = (y0, step, n, op) => Array.from({length: n}, (_, i) => {
  const y = (y0 + i * step).toFixed(2);
  return `<path d="M60 ${y}H140" stroke="#000" stroke-opacity="${op}" stroke-width=".7"/><path d="M60 ${(y0 + i * step + .8).toFixed(2)}H140" stroke="#fff" stroke-opacity="${(op * 1.4).toFixed(2)}" stroke-width=".5"/>`;
}).join('');

